\title{Schur Q-Polynomials and Kontsevich-Witten Tau Function}

\author{Xiaobo Liu \thanks{Research was partially supported by NSFC grants 11890662 and 11890660.}, Chenglang Yang}



\date{}

\begin{document}



\maketitle


\begin{abstract}
	Using matrix model, Mironov and Morozov recently gave a formula which represents Kontsevich-Witten tau-function as a linear expansion of Schur Q-polynomials.  In this paper, we will show directly that the Q-polynomial expansion in this formula satisfies the Virasoro constraints, and consequently obtain a proof of this formula without using matrix model. We also give a proof for Alexandrov's conjecture that  Kontsevich-Witten tau-function is a hypergeometric tau-function of the BKP hierarchy after re-scaling.
\end{abstract}

.}


\title{Q-polynomial expansion for Br\'{e}zin-Gross-Witten tau-function}
\author{Xiaobo Liu \thanks{Research was partially supported by NSFC grants 11890662 and 11890660.}, Chenglang Yang}
\date{}

\begin{document}
\maketitle

\begin{abstract}
	In this paper, we prove a conjecture of Alexandrov that the generalized Br\'{e}zin-Gross-Witten tau-functions are hypergeometric
tau functions of BKP hierarchy after re-scaling. In particular, this shows that the original BGW tau-function, which has enumerative geometric interpretations, can be represented as a linear combination of Schur Q-polynomials with simple coefficients.
\end{abstract}

.}

\title{Action of Virasoro operators on Hall-Littlewood polynomials}

\author{Xiaobo Liu \thanks{Research was partially supported by NSFC grants 11890662 and 11890660.}, Chenglang Yang}

\date{}

\begin{document}
\maketitle


\begin{abstract}
In this paper, we prove formulas for the action of Virasoro operators on Hall-Littlewood polynomials at roots of unity.
\end{abstract}

.}

\author{Xiaobo Liu \thanks{Research was partially supported by NSFC grants 11890662 and 12341105.},
	Chenglang Yang \thanks{Research was partially supported by NSFC grants 12288201, 12401079 and PSFC grants 2023M743717, BX20240407.}}

\date{}

\begin{document}
\title{Action of $W$-type operators on Schur functions and Schur Q-functions}

\maketitle

\begin{abstract}
In this paper, we investigate a series of W-type differential operators, which appear naturally in the symmetry algebras of
KP and BKP hierarchies. In particular, they include all operators in the W-constraints for tau-functions of higher KdV hierarchies which satisfy the string equation. We will give simple uniform formulas for actions of these operators on all ordinary Schur functions and Schur Q-functions.
As applications of such formulas, we will give new simple proofs for Alexandrov's conjecture and Mironov-Morozov's formula, which express the Br\'{e}zin-Gross-Witten and Kontsevich-Witten tau-functions as linear combinations of Q-functions with simple coefficients respectively.
\end{abstract}



